mapper.insert:
INSERT INTO file (
    file_name
    , save_file_name
    , file_path
    , file_extension
    , file_size
    , rgtr
    , request_source
    , checksum
    , prsinfo_yn
) VALUES (
    #{fileName}
    , #{saveFileName}
    , #{filePath}
    , #{fileExtension}
    , #{fileSize}
    , #{rgtr}
    , #{requestSource}
    , #{checksum}
    , #{prsInfoYn}
)

INSERT INTO file_download_log (
    file_idx
    , file_name
    , user_id
    , access_ip
    , request_source
) VALUES (
    #{fileIdx}
    , #{fileName}
    , #{userId}
    , #{accessIp}
    , #{requestSource}
);

mapper.update:
UPDATE file
SET del_yn = CASE id

        WHEN #{item.fileIdx} THEN #{item.delYn}

    END,
    del_dt = CASE id

        WHEN #{item.fileIdx} THEN #{item.delDt}

    END
WHERE id IN

    #{item.fileIdx}

mapper.select:
/* FileMapper.selectFileInfo */ SELECT a1.`id` AS fileIdx , a1.file_name AS fileName , a1.save_file_name AS saveFileName , a1.file_path AS filePath , a1.file_extension AS fileExtension , a1.file_size AS fileSize , a1.rgtr , a1.reg_dt AS regDt , a1.request_source AS requestSource , a1.checksum AS checksum , a1.del_yn AS delYn , a1.prsinfo_yn AS prsInfoYn
, CASE /* (1) 본인 파일 — 생성자(rgtr)와 요청자가 같은 경우. 양쪽 모두 user.sp_user_id 형식 */ WHEN a1.rgtr = #{rgtr} THEN 'Y'
/* (2) 요청자=교사 — 생성자가 내 그룹 멤버(학생) 또는 같은 그룹의 다른 호스트 교사 */ WHEN EXISTS ( SELECT 1 FROM user u_req INNER JOIN group_info gi_req ON gi_req.host_user_no = u_req.user_no WHERE u_req.sp_user_id = #{rgtr} AND ( /* 생성자 = 같은 그룹의 학생 (sp_user_id → user_no 변환 후 group_member 매칭) */ EXISTS ( SELECT 1 FROM group_member gm INNER JOIN user u_creator_st ON u_creator_st.user_no = gm.user_no WHERE gm.group_id = gi_req.group_id AND u_creator_st.sp_user_id = a1.rgtr ) /* 또는 생성자 = 같은 그룹의 다른 호스트 교사 */ OR EXISTS ( SELECT 1 FROM group_info gi_creator INNER JOIN user u_creator ON gi_creator.host_user_no = u_creator.user_no WHERE gi_creator.group_id = gi_req.group_id AND u_creator.sp_user_id = a1.rgtr ) ) ) THEN 'Y'
/* (3) 요청자=교사 — 다른 그룹 교사가 생성한 파일이지만, 파일의 대상 학생(tdri.stdt_id)이 내 그룹에 존재 file 과 tb_dgnss_result_info 의 file_url / summary_file_url 매칭으로 대상 학생 추론 */ WHEN EXISTS ( SELECT 1 FROM user u_req INNER JOIN group_info gi_req ON gi_req.host_user_no = u_req.user_no INNER JOIN group_member gm_target ON gm_target.group_id = gi_req.group_id INNER JOIN tb_dgnss_result_info tdri ON gm_target.stdt_id = tdri.stdt_id WHERE u_req.sp_user_id = #{rgtr} AND ( ( tdri.file_url IS NOT NULL AND tdri.file_url != '' AND a1.file_name = SUBSTRING_INDEX(tdri.file_url, '/', -1) AND a1.file_path = CONCAT( SUBSTRING_INDEX(tdri.file_url, '/', LENGTH(tdri.file_url) - LENGTH(REPLACE(tdri.file_url, '/', ''))), '/') ) OR (tdri.summary_file_url IS NOT NULL AND tdri.summary_file_url != '' AND a1.file_name = SUBSTRING_INDEX(tdri.summary_file_url, '/', -1) AND a1.file_path = CONCAT( SUBSTRING_INDEX(tdri.summary_file_url, '/', LENGTH(tdri.summary_file_url) - LENGTH(REPLACE(tdri.summary_file_url, '/', ''))), '/') ) ) ) THEN 'Y'
/* (4) 요청자=학생 — 생성자가 내가 속한 그룹의 호스트 교사 */ WHEN EXISTS ( SELECT 1 FROM user u_req_st INNER JOIN group_member gm_req ON gm_req.user_no = u_req_st.user_no INNER JOIN group_info gi ON gm_req.group_id = gi.group_id INNER JOIN user u_host ON gi.host_user_no = u_host.user_no WHERE u_req_st.sp_user_id = #{rgtr} AND u_host.sp_user_id = a1.rgtr ) THEN 'Y'
ELSE 'N' END downloadAuthYn
, 'Y' AS downloadAuthYn
FROM file a1 WHERE 1=1
AND id = #{fileIdx}
AND file_path = #{filePath} AND file_name = #{fileName} ORDER BY `id` DESC LIMIT 1

/* FileMapper.selectFileInfoWithPionada */ SELECT a1.`id` AS fileIdx , a1.file_name AS fileName , a1.save_file_name AS saveFileName , a1.file_path AS filePath , a1.file_extension AS fileExtension , a1.file_size AS fileSize , a1.rgtr , a1.reg_dt AS regDt , a1.request_source AS requestSource , a1.checksum AS checksum , a1.del_yn AS delYn , a1.prsinfo_yn AS prsInfoYn FROM file a1 WHERE 1=1
AND id = #{fileIdx}
AND file_path = #{filePath} AND file_name = #{fileName} ORDER BY `id` DESC LIMIT 1

/* FileMapper.selectTcListFromCreator */
SELECT u.tc_id
FROM group_info gi
         INNER JOIN user u ON gi.host_user_no = u.user_no
         INNER JOIN group_member gm ON gi.group_id = gm.group_id
WHERE gm.stdt_id = #{creator}

/* FileMapper.selectFileAuthStudent */
SELECT gm.stdt_id
FROM group_info gi
         INNER JOIN user u ON gi.host_user_no = u.user_no
         INNER JOIN group_member gm ON gi.group_id = gm.group_id
WHERE u.tc_id = #{creator}
  AND gm.stdt_id = #{reader}
